import{_ as a}from"./chunks/3221738a8c152b28cb94c27ff9bed5c8.GjXcMEZu.js";import{_ as n,c as t,a2 as e,o}from"./chunks/framework.BnrAgU0Y.js";const r="/bllm/assets/80e5fa6f5d092c569eb6cb0c86427e50.1GBlEXJL.png",u=JSON.parse('{"title":"Memory chatbot","description":"Memory chatbot","frontmatter":{"title":"Memory chatbot","description":"Memory chatbot","layout":"doc"},"headers":[],"relativePath":"langflow/tutorials-memory-chatbot.md","filePath":"langflow/tutorials-memory-chatbot.md"}'),l={name:"langflow/tutorials-memory-chatbot.md"};function i(p,s,c,g,m,d){return o(),t("div",null,s[0]||(s[0]=[e('<h1 id="memory-chatbot" tabindex="-1">Memory chatbot <a class="header-anchor" href="#memory-chatbot" aria-label="Permalink to &quot;Memory chatbot&quot;">​</a></h1><p>该流程扩展了<a href="/bllm/starter-projects-basic-prompting.html">基本提示流程</a>，增加了一个<strong>聊天记忆</strong>组件，该组件可以存储最多100条之前的聊天消息，并使用这些消息为当前对话提供上下文。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li><a href="/bllm/get-started-installation.html">已安装并运行 Langflow</a></li><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">已创建 OpenAI API 密钥</a></li></ul><h2 id="创建记忆聊天机器人的流程" tabindex="-1">创建记忆聊天机器人的流程 <a class="header-anchor" href="#创建记忆聊天机器人的流程" aria-label="Permalink to &quot;创建记忆聊天机器人的流程&quot;">​</a></h2><ol><li>在 Langflow 仪表板中，点击 <strong>New Flow</strong>（新建流程）。</li><li>选择 <strong>Memory Chatbot</strong>（记忆聊天机器人）。</li><li><strong>Memory Chatbot</strong> 流程即被创建。</li></ol><p><img src="'+r+`" alt=""></p><p>该流程为“基础提示”流添加了一个<strong>聊天记忆</strong>组件。此组件会检索以前的消息，并将它们发送到<strong>提示</strong>组件，以便用上下文信息填充<strong>模板</strong>的一部分。</p><p>要查看模板，请单击<strong>提示</strong>组件中的<strong>模板</strong>字段。<strong>提示</strong>告诉<strong>OpenAI模型</strong>组件如何响应输入。</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are a helpful assistant that answers questions.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Use markdown to format your answer, properly embedding images and urls.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">History:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{memory}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>在此提示中，<code>{memory}</code>代码在组件中创建了一个名为<strong>memory</strong>的新输入端口。<strong>聊天记忆</strong>组件连接到此端口，用于存储来自<strong>操场</strong>的聊天消息。</p><p>这为<strong>OpenAI</strong>组件提供了先前聊天消息的记忆。</p><h2 id="运行记忆型聊天机器人流程" tabindex="-1">运行记忆型聊天机器人流程 <a class="header-anchor" href="#运行记忆型聊天机器人流程" aria-label="Permalink to &quot;运行记忆型聊天机器人流程&quot;">​</a></h2><ol><li>打开 <strong>Playground</strong>。</li><li>输入多个问题。例如，尝试输入以下对话：</li></ol><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hi, my name is Luca.</span></span>
<span class="line"><span>Please tell me about PostgreSQL.</span></span>
<span class="line"><span>What is my name?</span></span>
<span class="line"><span>What is the second subject I asked you about?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>聊天机器人会记住你的名字和之前的问题。</p><ol start="3"><li>要查看 <strong>消息日志</strong> 面板，点击 <img src="" alt="Horizontal ellipsis">，然后点击 <strong>消息日志</strong>。<br><strong>消息日志</strong> 面板显示所有之前的消息，每段对话按照 <code>session_id</code> 排序。</li></ol><p><img src="`+a+'" alt=""></p><h2 id="使用会话-id-与记忆聊天机器人流程" tabindex="-1">使用会话 ID 与记忆聊天机器人流程 <a class="header-anchor" href="#使用会话-id-与记忆聊天机器人流程" aria-label="Permalink to &quot;使用会话 ID 与记忆聊天机器人流程&quot;">​</a></h2><p><code>session_id</code> 是 Langflow 中用于存储 AI 与用户之间会话的唯一标识符。当会话开始时会创建一个 <code>session_id</code>，其后该会话中的所有消息均与之关联。</p><p>在您创建的 <strong>记忆聊天机器人</strong> 流程中，<strong>聊天记忆</strong> 组件通过 <strong>会话 ID</strong> 引用过去的交互。您可以通过修改 <strong>会话 ID</strong> 值来切换不同的会话历史来演示这一点。</p><ol><li>在 <strong>聊天记忆</strong> 和 <strong>聊天输入</strong> 组件的 <strong>会话 ID</strong> 字段中，添加一个像 <code>MySessionID</code> 这样的 <strong>会话 ID</strong> 值。</li><li>现在，当您在 <strong>Playground</strong> 中发送新消息时，您应该会在 <strong>消息日志</strong> 窗格中看到一个新的记忆被创建。</li><li>注意您的对话如何存储在不同的记忆会话中。</li></ol><p>在 <a href="/bllm/components-memories.html">记忆</a> 部分了解更多关于聊天记忆的信息。</p>',23)]))}const y=n(l,[["render",i]]);export{u as __pageData,y as default};
